  ('Q1149912', '2005 Belize unrest', 'Two separate but related incidents of civil unrest in the Central American country of Belize occurred in January and April.', 2005, NULL, NULL, NULL, NULL, NULL, 'year', '2005', 57, 'https://en.wikipedia.org/wiki/2005_Belize_unrest'),
  ('Q48782261', 'Belizean territorial dispute referendum, 2019', 'A referendum on the territorial dispute with Guatemala was held in Belize on 8 May 2019. Voters were asked whether the territorial dispute with neighbouring Guatemala should be referred to the International Court of Justice.', 2019, 5, 8, NULL, NULL, NULL, 'day', '8 May 2019', 39, 'https://en.wikipedia.org/wiki/2019_Belizean_territorial_dispute_referendum');

